// Contrato con Entry. v2 no necesita estado en conversation_sessions: la continuidad la
// lleva la memoria del agente, así que flujo_activo y los pending_*/slot_* van a null y Entry
// los limpia solos. `intent` NO puede ser null: Entry lo usa para decidir si el saludo
// genérico es redundante detrás del aviso de privacidad, y aquí no hay saludo enlatado.
const out = $json ?? {};
const reply = (out.output ?? '').toString().trim();
if (!reply) {
  console.log('Core v2: el agente no devolvió texto. ' + JSON.stringify(out).slice(0, 300));
}
return [{ json: {
  ok: true,
  intent: 'v2',
  reply_to_user: reply || 'Perdona, se me ha cruzado un cable. ¿Me lo repites?',
  needs_user_reply: true,
  flujo_activo: null,
  contact_id: null,
  result: null,
} }];
